<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><style>body{font-family:DejaVu Sans;direction:rtl}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #bbb}</style><body><h1>تقرير طبي #{{$record->id}}</h1><table><tr><th>اسم المريض</th><td>{{$record->patient_name}}</td><th>رقم الملف</th><td>{{$record->file_number}}</td></tr><tr><th>تاريخ الميلاد</th><td>{{$record->birth_date}}</td><th>الطبيب</th><td>{{$record->doctor}}</td></tr><tr><th>الدخول</th><td>{{$record->entry_date}}</td><th>الخروج</th><td>{{$record->exit_date}}</td></tr><tr><th>التشخيص</th><td colspan="3">{{$record->medical_diagnosis}}</td></tr><tr><th>العلاج</th><td colspan="3">{{$record->treatment}}</td></tr><tr><th>التوصية</th><td colspan="3">{{$record->recommendation}}</td></tr><tr><th>القرار</th><td colspan="3">{{$record->manager_reply==1?'تمت الموافقة':($record->manager_reply==2?'مرفوض':'معلق')}} {{$record->manager_reply_reason}}</td></tr></table></body></html>
